/* aarch64 backend for cross_core_signal.h. The x86_64 backend pokes the
 * Local APIC's ICR to make one specific other core take a fixed vector;
 * on GICv3 the same operation is a Software Generated Interrupt --
 * interrupt IDs 0-15, per-PE by nature, generated by writing the
 * ICC_SGI1R_EL1 system register (MRS/MSR, not MMIO). Everything
 * ARM-specific about cross-core preemption signaling lives in this one
 * file -- nothing above cross_core_signal.h changes to accommodate it. */
#include "cross_core_signal.h"
#include "irq.h"
#include "mmio.h"
#include "serial.h"
#include <stdint.h>

/* GIC interrupt ID 0. Interrupt IDs 0-15 are the SGIs, so this is the
 * first one. irq_aarch64.c already sets every interrupt to Group 1
 * (non-secure) in GICD_IGROUPR, and ICC_SGI1R_EL1 signals Group 1 SGIs
 * -- consistent, no group mismatch to work around. */
#define CROSS_CORE_SIGNAL_SGI 0

/* Distributor Set-Enable register: write 1 to enable that interrupt,
 * write 0 is ignored; 32 interrupts per 32-bit register, so SGI 0 lives
 * in the very first one at offset 0x0100. Same value irq_aarch64.c uses
 * -- that file keeps it file-local, so this one does too, exactly like
 * the x86_64 backend keeps its own LAPIC_REG_* copy rather than leaning
 * on another file's private defines. */
#define GICD_ISENABLER 0x0100
#define GICD_SGIR       0x0f00  /* GICv2: target-list SGI generation */

/* GIC distributor base, this file's own copy -- same NULL-tolerant
 * design as irq_aarch64.c's g_gicd_base and serial_aarch64.c's
 * g_pl011_base. NULL means the distributor hasn't been configured yet,
 * in which case enabling SGI 0 is deferred rather than faulted on. */
static volatile uint8_t *g_gicd_base = NULL;
static int g_gic_v2 = 0;

/* Set the distributor base so the SGI can actually be enabled in
 * hardware. Mirrors irq_aarch64_set_base()/serial_aarch64_set_base():
 * not declared in a header, the bring-up code forward-declares it.
 * Wiring this into the ARM boot path happens in the smp_aarch64 unit. */
void cross_core_signal_aarch64_set_base(void *base)
{
    g_gicd_base = (volatile uint8_t *)base;
}

void cross_core_signal_aarch64_set_gic_v2(void)
{
    g_gic_v2 = 1;
}

uint64_t cross_core_signal_my_target(void)
{
    /* On x86_64 the target is the Local APIC ID; on ARM it is the
     * MPIDR, which cross_core_signal_send() decomposes back into
     * affinity fields. Read the FULL register, not a masked affinity
     * byte: the layout send() expects is Aff0=[7:0], Aff1=[15:8],
     * Aff2=[23:16], Aff3=[39:32] exactly as hardware presents it.
     * Valid on whichever core executes this, and callers above
     * cross_core_signal.h never inspect the value it returns. */
    uint64_t mpidr;
    __asm__ volatile("mrs %0, mpidr_el1" : "=r"(mpidr));
    return mpidr;
}

void cross_core_signal_send(uint64_t target)
{
    /* Decompose the MPIDR value my_target() produced on the core we are
     * trying to reach -- same field positions, read back out again. */
    uint64_t aff0 = (target >> 0) & 0xFFull;   /* core within cluster  */
    uint64_t aff1 = (target >> 8) & 0xFFull;   /* cluster              */
    uint64_t aff2 = (target >> 16) & 0xFFull;  /* chip                 */
    uint64_t aff3 = (target >> 32) & 0xFFull;  /* chip descriptor      */

    if (g_gic_v2) {
        /* GICv2 targets up to eight CPU interfaces via GICD_SGIR's
         * CPUTargetList [23:16]. There is no ICC_SGI1R_EL1 on v2. */
        if (g_gicd_base && aff0 < 8 && aff1 == 0 && aff2 == 0 && aff3 == 0) {
            mmio_write32((volatile void *)(g_gicd_base + GICD_SGIR),
                         (uint32_t)(1u << aff0) << 16);
        }
        return;
    }

    /* ICC_SGI1R_EL1: Aff3[55:48], Aff2[39:32], Aff1[23:16], and
     * TargetList[15:0] for Aff0. SGI 0 is INTID=0. RS stays zero, so
     * this backend only targets Aff0 0..15; never alias a higher target. */
    if (aff0 >= 16) {
        return;
    }
    uint64_t sgi1r = (aff3 << 48) | (aff2 << 32) | (aff1 << 16) |
                     (1ull << aff0);
    __asm__ volatile("msr icc_sgi1r_el1, %0" :: "r"(sgi1r));
}

void cross_core_signal_install_handler(void (*handler)(void))
{
    /* The EL1 exception table calls irq_aarch64_dispatch, which
     * acknowledges SGI 0 and invokes this handler before EOI. */
    irq_install_handler(CROSS_CORE_SIGNAL_SGI, (void *)handler);

    /* GICv2 enables SGI 0 in the distributor. On GICv3 the handler
     * registration above already enabled it in this core's redistributor. */
    if (g_gic_v2 && g_gicd_base) {
        mmio_write32((volatile void *)(g_gicd_base + GICD_ISENABLER),
                     1u << CROSS_CORE_SIGNAL_SGI);
        kprintf("[coreinit]   cross_core_signal: SGI %d enabled in GIC distributor\n",
                CROSS_CORE_SIGNAL_SGI);
    } else if (!g_gic_v2) {
        kprintf("[coreinit]   cross_core_signal: SGI %d enabled in GICR\n",
                CROSS_CORE_SIGNAL_SGI);
    } else {
        kprintf("[coreinit]   cross_core_signal: GIC distributor base not set, "
                "SGI %d will be enabled when it is\n", CROSS_CORE_SIGNAL_SGI);
    }
}
